import { NextRequest, NextResponse } from 'next/server';
import { getAdoptionGoogleOAuthRecord, deleteAdoptionGoogleOAuthRecord } from '@/app/lib/server/adoption-google-oauth-store';
import { requireAuth } from '@/server/middleware/authenticate';
import { getAdoptionPaymentRecord } from '@/app/lib/server/adoption-payment-store';

/**
 * GET /api/adoptions/[id]/google-oauth
 *
 * Initiates Google OAuth2 for a sponsor to authorize SufiPulse to
 * manage campaigns in their Google Ads account.
 *
 * Scopes requested:
 *   - https://www.googleapis.com/auth/adwords  (Google Ads API)
 *
 * Flow:
 *   1. Sponsor clicks "Connect Google Ads" in AdoptTab
 *   2. Browser hits this route → redirects to Google consent screen
 *   3. After consent, Google redirects to /api/adoptions/[id]/google-oauth/callback
 *   4. Callback exchanges code for access_token + refresh_token
 *   5. Tokens stored in adoption record; sponsor redirected back to release page
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const authResult = await requireAuth(request);
  if (authResult instanceof NextResponse) return authResult;

  const { id } = await params;

  const paymentRecord = await getAdoptionPaymentRecord(id);
  if (paymentRecord?.userId && paymentRecord.userId !== authResult.id) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
  }

  const clientId = process.env.GOOGLE_ADS_CLIENT_ID;
  const appUrl = process.env.NEXT_PUBLIC_APP_URL || 'http://localhost:3000';

  if (!clientId) {
    return NextResponse.json(
      { error: 'Google OAuth is not configured. Set GOOGLE_ADS_CLIENT_ID.' },
      { status: 503 }
    );
  }

  // Optional release slug so the callback can redirect back to the release page
  const returnSlug = request.nextUrl.searchParams.get('returnSlug') || '';
  const state = JSON.stringify({ adoptionId: id, returnSlug });

  const redirectUri = `${appUrl}/api/google-oauth/callback`;

  const oauthUrl = new URL('https://accounts.google.com/o/oauth2/v2/auth');
  oauthUrl.searchParams.set('client_id', clientId);
  oauthUrl.searchParams.set('redirect_uri', redirectUri);
  oauthUrl.searchParams.set('response_type', 'code');
  oauthUrl.searchParams.set('scope', 'https://www.googleapis.com/auth/adwords');
  oauthUrl.searchParams.set('access_type', 'offline');
  oauthUrl.searchParams.set('prompt', 'consent');
  oauthUrl.searchParams.set('state', state);

  return NextResponse.redirect(oauthUrl.toString());
}

/**
 * DELETE /api/adoptions/[id]/google-oauth
 *
 * Revokes the stored OAuth token with Google and removes the local record.
 */
export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const authResult = await requireAuth(request);
  if (authResult instanceof NextResponse) return authResult;

  const { id } = await params;

  const paymentRecord = await getAdoptionPaymentRecord(id);
  if (paymentRecord?.userId && paymentRecord.userId !== authResult.id) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
  }

  const record = await getAdoptionGoogleOAuthRecord(id);

  if (record?.accessToken) {
    try {
      await fetch(
        `https://oauth2.googleapis.com/revoke?token=${encodeURIComponent(record.accessToken)}`,
        { method: 'POST', headers: { 'Content-Type': 'application/x-www-form-urlencoded' } }
      );
    } catch {
      // Non-fatal — still delete the local record
    }
  }

  await deleteAdoptionGoogleOAuthRecord(id);

  return NextResponse.json({ disconnected: true });
}
